mapper.sql:

where 1 = 1
and n.use_yn = #{useYn}
and n.ack_required_yn = #{ackRequiredYn}

  and (n.title ilike '%' || #{q} || '%' escape '\' or c.cust_cd ilike '%' || #{q} || '%' escape '\' or c.cust_nm ilike '%' || #{q} || '%' escape '\'
       or i.item_cd ilike '%' || #{q} || '%' escape '\' or k.class_cd ilike '%' || #{q} || '%' escape '\')

mapper.update:
update wms_ship_note
   set cust_id = #{f.custId}, item_class_id = #{f.itemClassId}, item_id = #{f.itemId}, title = #{f.title}, body = #{f.body},
       ack_required_yn = #{f.ackRequiredYn}, use_yn = #{f.useYn}, sort_no = #{f.sortNo},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where note_id = #{f.noteId} and row_ver = #{rowVer}
